import { useState } from "react";

interface UseControlledOpenProps {
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
}

interface UseControlledOpenResult {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  close: () => void;
}

export const useControlledOpen = ({
  open,
  onOpenChange,
}: UseControlledOpenProps): UseControlledOpenResult => {
  const [internalOpen, setInternalOpen] = useState(false);

  // Determine if the component is controlled or uncontrolled
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  const setIsOpen = (newOpen: boolean) => {
    if (!isControlled) {
      setInternalOpen(newOpen);
    }
    if (onOpenChange) {
      onOpenChange(newOpen);
    }
  };

  const close = () => setIsOpen(false);

  return { close, isOpen, setIsOpen };
};

"use client";

import Link from "next/link";
import * as React from "react";

export interface LinkableProps {
  href?: string | undefined;
  external?: boolean | undefined;
  target?: string | undefined;
  rel?: string | undefined;
  as?: React.ElementType | undefined;
}
export const useLinkableComponent = <T extends LinkableProps>({
  href,
  external,
  as = "div",
  ...rest
}: T) => {
  const isExternal =
    external ??
    (href?.startsWith("http") ||
      href?.startsWith("mailto:") ||
      href?.startsWith("tel:"));
  if (href) {
    if (isExternal) {
      return {
        Component: "a" as const,
        href,
        linkProps: {
          rel: "noopener noreferrer",
          target: "_blank",
          ...rest,
        },
      };
    }
    return {
      Component: Link,
      href,
      linkProps: {
        ...rest,
      },
    };
  }
  return {
    Component: as,
    href,
    linkProps: {
      ...rest,
    },
  };
};

"use client";

import React from "react";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { ReactFC } from "@/lib/types";
import { useControlledOpen } from "@/registry/hooks/useControlledOpen";
import { BottomDrawerMenu } from "@/registry/new-york/bottom-drawer/BottomDrawerMenu";
import { useKitzeUI } from "@/registry/new-york/kitze-ui-context/KitzeUIContext";
import { MenuProvider } from "@/registry/new-york/menu-context/MenuContext";

// Define MobileViewType for Dropdown
export type DropdownMobileViewType = "keep" | "bottom-drawer";
export interface SimpleDropdownMenuClassNames {
  content?: string | undefined;
  drawerContent?: string | undefined;
}
export interface SimpleDropdownMenuProps {
  // This is the trigger
  children: React.ReactNode;
  // This is the menu content
  content: React.ReactNode;
  classNames?: SimpleDropdownMenuClassNames | undefined;
  align?: "start" | "center" | "end" | undefined;
  side?: "top" | "right" | "bottom" | "left" | undefined;
  closeOnClick?: boolean | undefined;
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  // Mobile specific props
  mobileView?: DropdownMobileViewType | undefined;
  drawerTitle?: string | undefined;
}
export const SimpleDropdownMenu: ReactFC<SimpleDropdownMenuProps> = ({
  children,
  content,
  classNames,
  align = "center",
  side = "bottom",
  closeOnClick = true,
  open,
  onOpenChange,
  mobileView = "keep",
  drawerTitle,
}) => {
  const { isMobile } = useKitzeUI();
  const { isOpen, setIsOpen, close } = useControlledOpen({
    onOpenChange,
    open,
  });

  // Function to close the menu when clicking on menu items
  const closeMenu = () => {
    if (closeOnClick) {
      close();
    }
  };

  // --- Mobile Rendering (Bottom Drawer) ---
  if (isMobile && mobileView === "bottom-drawer") {
    return (
      <BottomDrawerMenu
        title={drawerTitle}
        open={isOpen}
        onOpenChange={setIsOpen}
        content={content}
        closeOnClick={closeOnClick}
        classNames={{ content: classNames?.drawerContent }}
      >
        {children}
      </BottomDrawerMenu>
    );
  }

  // --- Default Dropdown Rendering (Desktop or mobileView='keep') ---
  return (
    <MenuProvider menuType="dropdown" closeMenu={closeMenu} open={isOpen}>
      <DropdownMenu open={isOpen} onOpenChange={setIsOpen}>
        <DropdownMenuTrigger
          render={
            React.isValidElement(children) ? (
              children
            ) : (
              <button type="button">{children}</button>
            )
          }
        />
        <DropdownMenuContent
          // Class for desktop dropdown
          className={classNames?.content}
          align={align}
          side={side}
        >
          {content}
        </DropdownMenuContent>
      </DropdownMenu>
    </MenuProvider>
  );
};

"use client";

import type { LucideIcon } from "lucide-react";
import React from "react";

import { ContextMenuItem } from "@/components/ui/context-menu";
import { DropdownMenuItem } from "@/components/ui/dropdown-menu";
import type { ReactFC } from "@/lib/types";
import { cn } from "@/lib/utils";
import type { LinkableProps } from "@/registry/hooks/useLinkableComponent";
import { useLinkableComponent } from "@/registry/hooks/useLinkableComponent";
import { BottomDrawerMenuItem } from "@/registry/new-york/bottom-drawer/BottomDrawerMenuItem";
import { HelpInfoCircle } from "@/registry/new-york/help-info-circle/HelpInfoCircle";
import { MenuShortcut } from "@/registry/new-york/kbd-shortcuts/MenuShortcut";
import { useMenuContext } from "@/registry/new-york/menu-context/MenuContext";

export interface CommonMenuItemProps extends LinkableProps {
  children: React.ReactNode;
  shortcut?: string | string[];
  hint?: string;
  leftIcon?: LucideIcon;
  rightIcon?: LucideIcon;
  className?: string;
  rootClassName?: string;
  textClassName?: string;
  leftIconClassName?: string;
  rightIconClassName?: string;
  shortcutClassName?: string;
  hintClassName?: string;
  disabled?: boolean;
  destructive?: boolean;
  onSelect?: (event: React.MouseEvent<HTMLElement>) => void;
  onBlur?: () => void;
  closeOnClick?: boolean;
  isLast?: boolean;
  href?: string;
  onClick?: (event: React.MouseEvent<HTMLElement>) => void;
  external?: boolean;
}

export const CommonMenuItem: ReactFC<CommonMenuItemProps> = ({
  children,
  shortcut,
  hint,
  leftIcon,
  rightIcon,
  className,
  rootClassName,
  textClassName,
  leftIconClassName,
  rightIconClassName,
  shortcutClassName,
  hintClassName,
  disabled,
  destructive,
  onSelect,
  onBlur,
  closeOnClick = true,
  isLast,
  onClick,
  external,
  ...rest
}) => {
  const { menuType, closeMenu } = useMenuContext();
  const { Component, href, linkProps } = useLinkableComponent({
    ...rest,
    external,
  });

  // Handle click with menu closing
  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    if (disabled) {
      event.preventDefault();
      return;
    }
    onSelect?.(event);
    if (!event.defaultPrevented) {
      onClick?.(event);
    }
    if (closeOnClick && !event.defaultPrevented) {
      closeMenu?.();
    }
  };

  // If we're in a bottom drawer, render the BottomDrawerMenuItem
  if (menuType === "bottom-drawer") {
    return (
      <BottomDrawerMenuItem
        leftIcon={leftIcon}
        rightIcon={rightIcon}
        className={cn(className, rootClassName)}
        disabled={disabled}
        destructive={destructive}
        onClick={handleClick}
        onBlur={onBlur}
        closeOnClick={false}
        textClassName={textClassName}
        leftIconClassName={leftIconClassName}
        rightIconClassName={rightIconClassName}
        shortcutClassName={shortcutClassName}
        hintClassName={hintClassName}
        href={rest.href}
        external={external}
        isLast={isLast}
        shortcut={shortcut}
        hint={hint}
      >
        {children}
      </BottomDrawerMenuItem>
    );
  }

  // For dropdown and context menus, use the existing implementation
  const MenuItem = menuType === "dropdown" ? DropdownMenuItem : ContextMenuItem;

  const iconClasses = cn(
    "size-5",
    "text-muted-foreground group-hover:text-current",
    destructive && "text-current"
  );

  const itemClasses = cn(
    className,
    rootClassName,
    destructive && "text-red-600 dark:text-red-400"
  );

  const content = (
    <>
      {leftIcon &&
        React.createElement(leftIcon, {
          className: cn(iconClasses, leftIconClassName),
        })}
      <span className={cn("min-w-0 flex-1", textClassName)}>{children}</span>
      {hint && (
        <span
          className={cn("inline-flex shrink-0 items-center", hintClassName)}
        >
          <HelpInfoCircle
            content={hint}
            iconClassName={cn("h-3.5 w-3.5", destructive && "text-current")}
          />
        </span>
      )}
      {rightIcon &&
        React.createElement(rightIcon, {
          className: cn(iconClasses, rightIconClassName),
        })}
      {shortcut && (
        <MenuShortcut
          shortcut={shortcut}
          destructive={destructive}
          className={shortcutClassName}
        />
      )}
    </>
  );

  return (
    <MenuItem
      className={cn(itemClasses, "group")}
      disabled={disabled}
      variant={destructive ? "destructive" : "default"}
      closeOnClick={false}
      onBlur={onBlur}
      onClick={handleClick}
      render={
        href && Component !== "div" ? (
          <Component href={href} {...linkProps} />
        ) : undefined
      }
    >
      {content}
    </MenuItem>
  );
};

